{
  "name": "notification-refactor-seed",
  "version": "1.0.0",
  "private": true,
  "type": "commonjs",
  "scripts": {
    "test": "node --test tests/*.test.js"
  }
}
const inputs = require('./inputs');
const { createRateLimiter } = require('./throttling');
const { createBaseFormatter } = require('./formatting');
const { createTransportDelivery } = require('./transport');

const DEFAULT_LOCALE = 'en-US';

/**
 * What a channel supplies. Everything else comes from the shared services.
 *
 * @typedef {object} ChannelStrategy
 * @property {string} channel - id used in send results, payload ids, throttle
 *   keys and as the transport key
 * @property {string} transportLabel - channel name in the "transport is not
 *   configured" error
 * @property {number} maxPerHour - sends allowed per user and category in any
 *   one-hour window
 * @property {(user: object) => void} [validateUser] - throws when the user
 *   cannot receive this channel; runs after the shared user checks
 * @property {(user: object, message: object, options: object) => boolean} [bypassRateLimit]
 *   - true skips the rate limit; checked before the shared `force` and urgent
 *   exemptions, and consent still applies
 * @property {(user: object, message: object) => {throttled: boolean, reason?: string, retryAt?: string|null}} [checkConsent]
 *   - runs after the rate limit passes or is bypassed
 * @property {(base: object, context: {user: object, message: object, options: object, now: () => Date}) => object} extendPayload
 *   - channel fields merged over the shared payload; a returned key replaces
 *   the shared value
 */

/**
 * Builds a notifier from a channel definition and the shared validation,
 * throttling, formatting and delivery services.
 *
 * `send` runs: validate user, validate message, throttle, format, deliver,
 * record. The step functions are also returned so callers can run one stage
 * alone. They do not depend on `this`, and reassigning one on the returned
 * object does not change what `send` does.
 *
 * @param {(options: object) => ChannelStrategy} defineChannel
 * @param {object} [options] - factory options: `transport`, `throttleStore`,
 *   `now`, `defaultLocale`, `maxPerHour`, plus channel-specific settings
 */
function createChannelNotifier(defineChannel, options = {}) {
  const {
    channel,
    transportLabel,
    maxPerHour,
    validateUser: validateChannelUser = () => {},
    bypassRateLimit = () => false,
    checkConsent = () => ({ throttled: false }),
    extendPayload
  } = defineChannel(options);

  const now = options.now || (() => new Date());
  const rateLimiter = createRateLimiter({
    channel,
    store: options.throttleStore || new Map(),
    maxPerHour,
    now
  });
  const formatBase = createBaseFormatter({
    channel,
    now,
    defaultLocale: options.defaultLocale || DEFAULT_LOCALE
  });
  const deliver = createTransportDelivery(options.transport || {}, channel, transportLabel);

  function validateUser(user) {
    inputs.validateUser(user);
    validateChannelUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    const exempt = bypassRateLimit(user, message, sendOptions)
      || sendOptions.force
      || inputs.isUrgent(message);

    if (!exempt) {
      const limit = rateLimiter.check(user, message);
      if (limit.throttled) {
        return limit;
      }
    }

    return checkConsent(user, message);
  }

  function format(user, message, sendOptions = {}) {
    const base = formatBase(user, message, sendOptions);
    return {
      ...base,
      ...extendPayload(base, { user, message, options: sendOptions, now })
    };
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    inputs.validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const payload = format(user, message, sendOptions);
    await deliver(payload);
    rateLimiter.record(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return {
    channel,
    send,
    validateUser,
    validateMessage: inputs.validateMessage,
    shouldThrottle,
    format,
    deliver,
    recordDelivery: rateLimiter.record
  };
}

module.exports = {
  createChannelNotifier
};
const { requireMarketingOptIn } = require('../throttling');

const DEFAULT_MAX_PER_HOUR = 8;
const DEFAULT_FROM = 'noreply@example.com';
const DEFAULT_REPLY_TO = 'support@example.com';
const DEFAULT_UNSUBSCRIBE_BASE_URL = 'https://example.com/unsubscribe';
const SECURITY_SUBJECT_PREFIX = '[Action Required] ';
const PREVIEW_LENGTH = 90;
// Mail in these categories explains why it was sent instead of offering an unsubscribe link.
const ACCOUNT_ACTIVITY_CATEGORIES = new Set(['transactional', 'security']);

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/**
 * Email channel. Options: `from`, `replyTo`, `unsubscribeBaseUrl`,
 * `maxPerHour` (default 8). Requires `user.email`; marketing mail also needs
 * `user.emailOptIn`.
 *
 * @param {object} options - factory options
 * @returns {import('../channelNotifier').ChannelStrategy}
 */
function defineEmailChannel(options) {
  const from = options.from || DEFAULT_FROM;
  const replyTo = options.replyTo || DEFAULT_REPLY_TO;
  const unsubscribeBaseUrl = options.unsubscribeBaseUrl || DEFAULT_UNSUBSCRIBE_BASE_URL;

  function footerFor(user, message) {
    if (ACCOUNT_ACTIVITY_CATEGORIES.has(message.category)) {
      return `Sent to ${user.email} because of recent account activity.`;
    }
    const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
    return `You can unsubscribe at ${url}.`;
  }

  return {
    channel: 'email',
    transportLabel: 'email',
    maxPerHour: options.maxPerHour || DEFAULT_MAX_PER_HOUR,

    validateUser(user) {
      if (!user.email || !user.email.includes('@')) {
        throw new TypeError('user.email is required for email notifications');
      }
    },

    checkConsent: requireMarketingOptIn('emailOptIn', 'email'),

    extendPayload(base, { user, message }) {
      const subjectPrefix = message.category === 'security' ? SECURITY_SUBJECT_PREFIX : '';
      const footer = footerFor(user, message);

      return {
        to: user.email,
        from,
        replyTo,
        subject: `${subjectPrefix}${base.title}`,
        text: `${base.body}\n\n${footer}`,
        html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
        preview: base.body.slice(0, PREVIEW_LENGTH)
      };
    }
  };
}

module.exports = {
  defineEmailChannel
};
const { isUrgent } = require('../inputs');

const DEFAULT_MAX_PER_HOUR = 50;
const DEFAULT_ICON = 'bell';
const DEFAULT_ACTION_URL = '/notifications';
const URGENT_EXPIRY_HOURS = 72;
const STANDARD_EXPIRY_HOURS = 168;
const MS_PER_HOUR = 60 * 60 * 1000;

/**
 * In-app channel. Options: `defaultIcon`, `defaultAction`, `maxPerHour`
 * (default 50). Rejects users with `disabledInApp`. Security messages skip
 * the rate limit. Send options `expiresInHours` and `actionUrl` override the
 * defaults.
 *
 * @param {object} options - factory options
 * @returns {import('../channelNotifier').ChannelStrategy}
 */
function defineInAppChannel(options) {
  const defaultIcon = options.defaultIcon || DEFAULT_ICON;
  const defaultAction = options.defaultAction || DEFAULT_ACTION_URL;

  return {
    channel: 'inapp',
    transportLabel: 'in-app',
    maxPerHour: options.maxPerHour || DEFAULT_MAX_PER_HOUR,

    validateUser(user) {
      if (user.disabledInApp) {
        throw new TypeError('in-app notifications are disabled for this user');
      }
    },

    bypassRateLimit(user, message) {
      return message.category === 'security';
    },

    extendPayload(base, { user, message, options: sendOptions, now }) {
      const expiresInHours = sendOptions.expiresInHours
        || (isUrgent(message) ? URGENT_EXPIRY_HOURS : STANDARD_EXPIRY_HOURS);
      const expiresAt = new Date(now().getTime() + expiresInHours * MS_PER_HOUR);

      return {
        userId: user.id,
        icon: message.icon || defaultIcon,
        actionUrl: sendOptions.actionUrl || message.actionUrl || defaultAction,
        read: false,
        expiresAt: expiresAt.toISOString(),
        preview: base.title
      };
    }
  };
}

module.exports = {
  defineInAppChannel
};
const { PREVIEW_LENGTH } = require('../formatting');

const DEFAULT_MAX_PER_HOUR = 20;
const DEFAULT_WORKSPACE = 'main';
const DEFAULT_SLACK_CHANNEL = '#general';

function blocksFor(base, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${base.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: base.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${base.metadata.category}`
        }
      ]
    }
  ];
}

/**
 * Slack channel. Options: `defaultWorkspace`, `defaultChannel`, `maxPerHour`
 * (default 20). Requires `user.slackId` or `user.slackChannel`. Replies sent
 * with a `threadTs` send option skip the rate limit.
 *
 * The payload's `channel` field is the Slack conversation (send option
 * `channel`, then `user.slackChannel`, then `defaultChannel`), not the
 * notification channel id.
 *
 * @param {object} options - factory options
 * @returns {import('../channelNotifier').ChannelStrategy}
 */
function defineSlackChannel(options) {
  const defaultWorkspace = options.defaultWorkspace || DEFAULT_WORKSPACE;
  const defaultChannel = options.defaultChannel || DEFAULT_SLACK_CHANNEL;

  return {
    channel: 'slack',
    transportLabel: 'slack',
    maxPerHour: options.maxPerHour || DEFAULT_MAX_PER_HOUR,

    validateUser(user) {
      if (!user.slackId && !user.slackChannel) {
        throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
      }
    },

    bypassRateLimit(user, message, sendOptions) {
      return Boolean(sendOptions.threadTs);
    },

    extendPayload(base, { user, options: sendOptions }) {
      const slackChannel = sendOptions.channel || user.slackChannel || defaultChannel;
      const mention = user.slackId ? `<@${user.slackId}> ` : '';
      const text = `${mention}*${base.title}*\n${base.body}`;

      return {
        workspace: user.slackWorkspace || defaultWorkspace,
        channel: slackChannel,
        threadTs: sendOptions.threadTs || null,
        text,
        blocks: blocksFor(base, mention),
        preview: text.replace(/\*/g, '').slice(0, PREVIEW_LENGTH)
      };
    }
  };
}

module.exports = {
  defineSlackChannel
};
const { isUrgent } = require('../inputs');
const { requireMarketingOptIn } = require('../throttling');

const DEFAULT_MAX_PER_HOUR = 4;
const DEFAULT_SENDER_ID = 'APP';
const DEFAULT_SEGMENT_LENGTH = 140;
const E164_PATTERN = /^\+[1-9]\d{6,14}$/;
const URGENT_PREFIX = 'URGENT: ';
const ELLIPSIS = '…';

/**
 * SMS channel. Options: `senderId`, `segmentLength` (default 140),
 * `maxPerHour` (default 4). Requires an E.164 `user.phone`; marketing
 * messages also need `user.smsOptIn`.
 *
 * Text is cut to one segment. Lengths are UTF-16 code units, so a cut can
 * land inside a surrogate pair.
 *
 * @param {object} options - factory options
 * @returns {import('../channelNotifier').ChannelStrategy}
 */
function defineSmsChannel(options) {
  const senderId = options.senderId || DEFAULT_SENDER_ID;
  const segmentLength = options.segmentLength || DEFAULT_SEGMENT_LENGTH;

  function truncate(value) {
    if (value.length <= segmentLength) {
      return value;
    }
    return `${value.slice(0, segmentLength - 1)}${ELLIPSIS}`;
  }

  return {
    channel: 'sms',
    transportLabel: 'sms',
    maxPerHour: options.maxPerHour || DEFAULT_MAX_PER_HOUR,

    validateUser(user) {
      if (!user.phone || !E164_PATTERN.test(user.phone)) {
        throw new TypeError('user.phone must be E.164 for SMS notifications');
      }
    },

    checkConsent: requireMarketingOptIn('smsOptIn', 'SMS'),

    extendPayload(base, { user, message }) {
      const prefix = isUrgent(message) ? URGENT_PREFIX : '';
      const text = truncate(`${prefix}${base.title} - ${base.body}`);

      return {
        to: user.phone,
        from: senderId,
        text,
        segments: Math.ceil(text.length / segmentLength),
        preview: text
      };
    }
  };
}

module.exports = {
  defineSmsChannel
};
const { createChannelNotifier } = require('./channelNotifier');
const { defineEmailChannel } = require('./channels/email');
const { defineSmsChannel } = require('./channels/sms');
const { defineSlackChannel } = require('./channels/slack');
const { defineInAppChannel } = require('./channels/inapp');

// Returns a plain `function`, not an arrow, so `new registry.email(options)`
// still yields a notifier as it did when the registry held classes.
function notifierFactory(defineChannel) {
  return function createRegisteredNotifier(options) {
    return createChannelNotifier(defineChannel, options);
  };
}

/** Channel id to notifier factory: `registry.email(options)` returns an email notifier. */
const registry = {
  email: notifierFactory(defineEmailChannel),
  sms: notifierFactory(defineSmsChannel),
  slack: notifierFactory(defineSlackChannel),
  inapp: notifierFactory(defineInAppChannel)
};

/**
 * @param {string} channel - a key of `registry`
 * @param {object} [options] - shared options (`transport`, `throttleStore`,
 *   `now`, `defaultLocale`, `maxPerHour`) plus channel-specific settings
 * @throws {TypeError} when `channel` is not registered
 */
function createNotifier(channel, options = {}) {
  // Own properties only: an inherited name such as `toString` or `constructor`
  // must not resolve to an Object.prototype member.
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (typeof factory !== 'function') {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

/** One notifier per registered channel, all built from the same options. */
function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
/**
 * Returns a delivery function for one transport key.
 *
 * The transport function is looked up on every call, so a transport wired up
 * after the notifier was created still works. It is called as a method, so
 * `this` stays bound to the transport object. Its return value is discarded.
 *
 * @param {object} transport - object holding one async function per channel
 * @param {string} key - property on `transport` to call, e.g. `email`
 * @param {string} label - channel name used in the "not configured" error
 */
function createTransportDelivery(transport, key, label) {
  return async function deliver(payload) {
    if (typeof transport[key] !== 'function') {
      throw new Error(`${label} transport is not configured`);
    }
    await transport[key](payload);
  };
}

module.exports = {
  createTransportDelivery
};
const { categoryOf } = require('./inputs');

const PREVIEW_LENGTH = 120;
const DEFAULT_PRIORITY = 'normal';
const ANONYMOUS_NAME = 'there';

/** Fills the `{{name}}`, `{{id}}` and `{{category}}` placeholders. */
function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || ANONYMOUS_NAME)
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, categoryOf(message));
}

/**
 * Builds the channel-neutral payload that channel strategies add fields to.
 * The returned formatter reads the clock twice: once for `id`, once for
 * `metadata.generatedAt`.
 *
 * @param {object} config
 * @param {string} config.channel
 * @param {() => Date} config.now
 * @param {string} config.defaultLocale
 */
function createBaseFormatter({ channel, now, defaultLocale }) {
  return function formatBase(user, message, options) {
    const id = `${channel}-${user.id}-${now().getTime()}`;
    const locale = options.locale || user.locale || defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    return {
      id,
      channel,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
      metadata: {
        category: categoryOf(message),
        priority: message.priority || DEFAULT_PRIORITY,
        generatedAt: now().toISOString()
      }
    };
  };
}

module.exports = {
  PREVIEW_LENGTH,
  createBaseFormatter
};
const DEFAULT_CATEGORY = 'general';
const URGENT_PRIORITY = 'urgent';

/**
 * Checks shared by every channel. Channel strategies add their own recipient
 * checks, which run only after these pass.
 * @throws {TypeError}
 */
function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

/** @throws {TypeError} */
function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

/** Category used for throttle keys, templates and payload metadata. */
function categoryOf(message) {
  return message.category || DEFAULT_CATEGORY;
}

function isUrgent(message) {
  return message.priority === URGENT_PRIORITY;
}

module.exports = {
  validateUser,
  validateMessage,
  categoryOf,
  isUrgent
};

