  const notifier = createNotifier('webhook', { transport: transportWithLog(log), throttleStore: new Map() });

  await notifier.send(
    { id: 'w2', webhookUrl: 'https://hooks.example.com/w2' },
    { title: 'T', body: 'B', category: 'billing' }
  );

  assert.equal(JSON.parse(log[0].json).category, 'billing');
});

test('webhook throttles at 10 per hour by default and honors maxPerHour', async () => {
  const now = () => new Date('2026-01-02T03:04:05.000Z');
  const user = { id: 'w3', webhookUrl: 'https://hooks.example.com/w3' };
  const message = { title: 'T', body: 'B' };

  const byDefault = createNotifier('webhook', { transport: transportWithLog([]), throttleStore: new Map(), now });
  for (let i = 0; i < 10; i++) {
    assert.equal((await byDefault.send(user, message)).status, 'sent');
  }
  const eleventh = await byDefault.send(user, message);
  assert.equal(eleventh.status, 'throttled');
  assert.match(eleventh.reason, /webhook hourly limit/);

  const custom = createNotifier('webhook', {
    transport: transportWithLog([]),
    throttleStore: new Map(),
    maxPerHour: 2,
    now
  });
  await custom.send(user, message);
  await custom.send(user, message);
  assert.equal((await custom.send(user, message)).status, 'throttled');
});

test('webhook rejects when its transport is not configured', async () => {
  const notifier = createNotifier('webhook', { transport: { email: async () => {} }, throttleStore: new Map() });

  await assert.rejects(
    () => notifier.send({ id: 'w4', webhookUrl: 'https://hooks.example.com/w4' }, { title: 'T', body: 'B' }),
    error => error.constructor === Error && error.message === 'webhook transport is not configured'
  );
});
